-- Création des types ENUM natifs PostgreSQL
CREATE TYPE role_enum AS ENUM ('YOUTH', 'GROUP_REFERENT', 'ADMIN', 'PARTNER', 'SUPER_ADMIN', 'PROJECT_MANAGER');
CREATE TYPE project_status_enum AS ENUM ('PENDING', 'VALIDATED_BY_REFERENT', 'REFUSED_BY_REFERENT', 'TRANSMITTED_TO_ADMIN', 'VALIDATED_BY_ADMIN', 'REFUSED_BY_ADMIN', 'VISIBLE_TO_PARTNERS', 'COMPLETED');
CREATE TYPE activity_category_enum AS ENUM ('WORKSHOP', 'TRAINING', 'MEETING', 'OUTING', 'EVENT', 'OTHER');
CREATE TYPE partner_level_enum AS ENUM ('SIMPLE', 'SPONSOR', 'STRATEGIC');
CREATE TYPE registration_status_enum AS ENUM ('REGISTERED', 'CANCELLED', 'ATTENDED', 'NO_SHOW');